'use client'

import { useId, useMemo, useState } from 'react'
import { EvidenceTable } from './EvidenceTable'
import { judgeEvidence, type EvidenceRow } from './evidence'
import { alignPlan, type ActualStep, type PlanStep } from './planactual'
import { PlanVsActual } from './PlanVsActual'
import { summarizeRun } from './run'
import { traceHealth, type HealthOptions } from './tracehealth'
import { TraceExplorer } from './TraceExplorer'
import { after } from './theatre'
import type { Span } from './trace'
import { cx, formatHours, pct } from './util'

export type RunInspectorProps = {
  title: string
  spans: Span[]
  /** With `actual`, adds the plan tab. */
  plan?: PlanStep[]
  actual?: ActualStep[]
  /** Adds the evidence tab. */
  evidence?: EvidenceRow[]
  /** How strictly to check the trace. See `traceHealth`. */
  health?: HealthOptions
  className?: string
}

type Tab = 'trace' | 'plan' | 'evidence' | 'cost' | 'health'
const usd = (n: number) => (n >= 1 ? `$${n.toFixed(2)}` : `$${n.toFixed(4)}`)
const secs = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(2)} s` : `${Math.round(ms)} ms`)

/**
 * One agent run, seen four ways, with the four questions people ask of a run answered first: did it finish, did it
 * follow the plan, were the tool calls sound, and does each value have a source. Every answer is worked out from the
 * spans, the plan and the evidence you pass in.
 */
export function RunInspector({ title, spans, plan, actual, evidence, health: healthOptions, className }: RunInspectorProps) {
  const run = useMemo(() => summarizeRun(spans), [spans])
  const path = useMemo(() => (plan && actual ? alignPlan(plan, actual) : null), [plan, actual])
  const proof = useMemo(() => (evidence ? judgeEvidence(evidence) : null), [evidence])
  const health = useMemo(() => traceHealth(spans, healthOptions), [spans, healthOptions])
  const tabs: [Tab, string][] = [['trace', 'Trace'], ...(path ? [['plan', 'Plan'] as [Tab, string]] : []), ...(proof ? [['evidence', 'Evidence'] as [Tab, string]] : []), ['cost', 'Cost'], ['health', health.fix ? `Trace health (${health.fix})` : 'Trace health']]
  const [tab, setTab] = useState<Tab>('trace')
  const base = useId()

  const finishedTone = run.outcome === 'finished' ? 'good' : run.outcome === 'empty' ? undefined : run.outcome === 'finished-with-errors' || run.outcome === 'stopped' ? 'warn' : 'bad'
  const facts: { tab: Tab; q: string; a: string; tone?: 'good' | 'warn' | 'bad' }[] = [
    { tab: 'trace', q: 'Did it finish', a: run.outcomeText, tone: finishedTone },
    ...(path ? [{ tab: 'plan' as Tab, q: 'Did it follow the plan', a: path.summary, tone: path.counts.asPlanned === path.counts.planned && !path.counts.extra ? ('good' as const) : ('warn' as const) }] : []),
    { tab: 'trace', q: 'Were the tool calls sound', a: run.toolCalls === 0 ? 'No tool calls.' : `${run.toolCalls - run.toolFailures} of ${run.toolCalls} tool calls succeeded.`, tone: run.toolFailures ? ('warn' as const) : ('good' as const) },
    ...(proof ? [{ tab: 'evidence' as Tab, q: 'Is every value sourced', a: proof.summary.text + '.', tone: proof.summary.conflicts ? ('bad' as const) : proof.summary.unsourced ? ('warn' as const) : ('good' as const) }] : []),
  ]

  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <h3 className="ol-title">{title}</h3>
        <span className="ol-sub ol-mono">{secs(run.durationMs)} · {run.spans} spans · {usd(run.costUsd)}</span>
      </div>
      <ul className="ol-runfacts">
        {facts.map((f, idx) => (
          <li key={f.q} className="ol-in" style={after(idx)}>
            <button type="button" className="ol-runfact" data-tone={f.tone} aria-label={`${f.q}. ${f.a} Open the ${f.tab} tab.`} onClick={() => setTab(f.tab)}>
              <span className="ol-sub">{f.q}</span>
              <span>{f.a}</span>
            </button>
          </li>
        ))}
      </ul>
      <div className="ol-tabs" role="tablist" aria-label="Run views">
        {tabs.map(([id, label]) => (
          <button key={id} type="button" role="tab" id={`${base}-t-${id}`} className="ol-tab" aria-selected={tab === id} aria-controls={`${base}-p-${id}`} onClick={() => setTab(id)}>{label}</button>
        ))}
      </div>
      <div role="tabpanel" id={`${base}-p-${tab}`} aria-labelledby={`${base}-t-${tab}`} className="ol-runpanel">
        {tab === 'trace' && <TraceExplorer title="Trace" spans={spans} />}
        {tab === 'plan' && path && plan && actual && <PlanVsActual title="Plan against actual" plan={plan} actual={actual} />}
        {tab === 'evidence' && evidence && <EvidenceTable title="Values and their sources" rows={evidence} />}
        {tab === 'health' && (
          <div>
            <p className="ol-sub ol-mb-3" role="status">{health.text}</p>
            <ul className="ol-health">
              {health.findings.map((f) => (
                <li key={f.check} className="ol-healthrow" data-severity={f.severity}>
                  <span className="ol-pill" data-tone={f.severity === 'fix' ? 'bad' : 'warn'}>{f.severity === 'fix' ? 'Fix' : 'Note'}</span>
                  <span>{f.text}<span className="ol-sub ol-mono"> {f.spans.slice(0, 4).join(', ')}{f.spans.length > 4 ? `, and ${f.spans.length - 4} more` : ''}</span></span>
                </li>
              ))}
            </ul>
          </div>
        )}
        {tab === 'cost' && (
          <div>
            <div className="ol-figs">
              <span><b>{usd(run.costUsd)}</b> <span className="ol-sub">total</span></span>
              <span><b>{(run.tokensIn + run.tokensOut).toLocaleString('en-US')}</b> <span className="ol-sub">tokens</span></span>
              <span><b>{formatHours(run.humanMs / 3_600_000)}</b> <span className="ol-sub">waiting on people</span></span>
            </div>
            <table className="ol-table">
              <thead><tr><th>Kind</th><th>Spans</th><th>Share of time</th><th>Tokens</th><th>Cost</th></tr></thead>
              <tbody>
                {run.byKind.map((k) => (
                  <tr key={k.kind}><td>{k.kind}</td><td className="ol-num">{k.count}</td><td className="ol-num">{pct(k.share, 0)}</td><td className="ol-num">{(k.tokensIn + k.tokensOut).toLocaleString('en-US')}</td><td className="ol-num">{usd(k.costUsd)}</td></tr>
                ))}
              </tbody>
            </table>
            {run.costliest.length > 0 && (
              <div className="ol-gatelist">
                <p className="ol-sub">Most expensive</p>
                <ul>{run.costliest.map((s) => <li key={s.id}><span>{s.name}</span><span className="ol-mono">{usd(s.costUsd ?? 0)}</span></li>)}</ul>
              </div>
            )}
          </div>
        )}
      </div>
    </section>
  )
}

// Rules for summarising one agent run. The point of each: the answers to "did it finish, what did it cost" come from
// the spans, not from anything the agent wrote about itself.
import { buildTree, cleanSpans, kindShares, type KindShare, type Span, type SpanKind } from './trace'

export type RunOutcome = 'finished' | 'finished-with-errors' | 'stopped' | 'failed' | 'empty'
export type KindCost = KindShare & { tokensIn: number; tokensOut: number; costUsd: number }
export type RunSummary = {
  outcome: RunOutcome
  /** One plain sentence for the outcome. */
  outcomeText: string
  spans: number
  durationMs: number
  failed: number
  blocked: number
  toolCalls: number
  toolFailures: number
  humanMs: number
  tokensIn: number
  tokensOut: number
  costUsd: number
  byKind: KindCost[]
  costliest: Span[]
}

/** A run is only "finished" when the top span is ok and nothing failed or was blocked inside it. */
export function summarizeRun(input: Span[]): RunSummary {
  const spans = cleanSpans(input)
  if (spans.length === 0) {
    return { outcome: 'empty', outcomeText: 'No spans were recorded.', spans: 0, durationMs: 0, failed: 0, blocked: 0, toolCalls: 0, toolFailures: 0, humanMs: 0, tokensIn: 0, tokensOut: 0, costUsd: 0, byKind: [], costliest: [] }
  }
  const roots = buildTree(spans)
  const root = roots[0]?.span
  const failed = spans.filter((s) => s.status === 'error').length
  const blocked = spans.filter((s) => s.status === 'blocked').length
  const start = Math.min(...spans.map((s) => s.startMs))
  const end = Math.max(...spans.map((s) => s.startMs + s.durationMs))
  const tools = spans.filter((s) => s.kind === 'tool')
  const cost = (k: SpanKind) => spans.filter((s) => s.kind === k)
  const byKind: KindCost[] = kindShares(roots).map((k) => ({
    ...k,
    tokensIn: cost(k.kind).reduce((n, s) => n + (s.tokens?.in ?? 0), 0),
    tokensOut: cost(k.kind).reduce((n, s) => n + (s.tokens?.out ?? 0), 0),
    costUsd: cost(k.kind).reduce((n, s) => n + (s.costUsd ?? 0), 0),
  }))
  let outcome: RunOutcome
  let outcomeText: string
  if (root?.status === 'error') {
    outcome = 'failed'
    outcomeText = 'The run failed.'
  } else if (blocked > 0) {
    outcome = 'stopped'
    outcomeText = `The run stopped at ${blocked === 1 ? 'a gate' : `${blocked} gates`}.`
  } else if (failed > 0) {
    outcome = 'finished-with-errors'
    outcomeText = `The run finished, with ${failed} failed ${failed === 1 ? 'span' : 'spans'}.`
  } else {
    outcome = 'finished'
    outcomeText = 'The run finished with no failures.'
  }
  return {
    outcome, outcomeText, spans: spans.length, durationMs: end - start, failed, blocked,
    toolCalls: tools.length, toolFailures: tools.filter((s) => s.status === 'error').length,
    humanMs: spans.filter((s) => s.kind === 'human').reduce((n, s) => n + s.durationMs, 0),
    tokensIn: spans.reduce((n, s) => n + (s.tokens?.in ?? 0), 0),
    tokensOut: spans.reduce((n, s) => n + (s.tokens?.out ?? 0), 0),
    costUsd: spans.reduce((n, s) => n + (s.costUsd ?? 0), 0),
    byKind,
    costliest: spans.filter((s) => (s.costUsd ?? 0) > 0).sort((a, b) => (b.costUsd ?? 0) - (a.costUsd ?? 0)).slice(0, 3),
  }
}

// Rules for whether a trace is worth reading. The point of each: a trace is easy to debug when each model call is
// its own step, tool calls sit under the step that asked for them, and names are stable. These are the things
// Langfuse's "what does a good trace look like" asks you to check by eye, turned into checks that run on the spans.
import { buildTree, cleanSpans, flatten, type Span } from './trace'

export type HealthCheck =
  | 'loop-wrapped'
  | 'tool-at-root'
  | 'orphan'
  | 'no-usage'
  | 'no-thinking'
  | 'generic-name'
  | 'noise'
  | 'error-silent'
  | 'outlives-parent'
export type HealthFinding = {
  check: HealthCheck
  /** `fix` makes the trace harder to debug. `note` is worth knowing. */
  severity: 'fix' | 'note'
  /** The spans it is about. */
  spans: string[]
  text: string
}
export type HealthOptions = {
  /** Look for reasoning on each model call, kept in `attrs.thinking` or `attrs.reasoning`. Off unless you record it. */
  expectThinking?: boolean
  /** Spans shorter than this, sharing a name, count as noise once there are `noiseCount` of them. */
  noiseMs?: number
  noiseCount?: number
}
export type TraceHealth = { findings: HealthFinding[]; fix: number; note: number; text: string }

const GENERIC = /^(span|trace|run|step|llm|tool|agent|call|function|unknown|untitled|\d+)$/i
const hasThinking = (s: Span) => ['thinking', 'reasoning'].some((k) => s.attrs && String(s.attrs[k] ?? '').length > 0)

export function traceHealth(input: Span[], options: HealthOptions = {}): TraceHealth {
  const spans = cleanSpans(input)
  const findings: HealthFinding[] = []
  const add = (f: HealthFinding) => findings.push(f)
  if (spans.length === 0) return { findings, fix: 0, note: 0, text: 'No spans to check.' }
  const byId = new Map(spans.map((s) => [s.id, s]))
  const nodes = flatten(buildTree(spans))
  const roots = nodes.filter((n) => n.depth === 0)

  // One model call wrapping the loop: it has model or tool calls inside it, so tokens and cost cannot be told apart per step.
  for (const n of nodes) {
    if (n.span.kind !== 'llm') continue
    const inner = flatten(n.children).filter((c) => c.span.kind === 'tool' || c.span.kind === 'llm')
    if (inner.length >= 2) {
      add({ check: 'loop-wrapped', severity: 'fix', spans: [n.span.id], text: `"${n.span.name}" is one model call with ${inner.length} calls inside it. Give each model call its own step, so you can see what the agent decided after each result and which call blew up the context.` })
    }
  }

  // A tool call hanging off the very top while other steps exist: it is not shown under the step that asked for it.
  const topSpans = roots.map((r) => r.span)
  if (topSpans.length > 1 || roots.some((r) => r.children.length > 0)) {
    const dangling = roots.filter((r) => r.span.kind === 'tool' && roots.length > 1).map((r) => r.span.id)
    if (dangling.length) add({ check: 'tool-at-root', severity: 'fix', spans: dangling, text: `${dangling.length === 1 ? 'A tool call sits' : `${dangling.length} tool calls sit`} at the top, not under the step that asked for ${dangling.length === 1 ? 'it' : 'them'}.` })
  }

  const orphans = input.filter((s) => s.parentId && s.parentId !== s.id && !byId.has(s.parentId)).map((s) => s.id)
  if (orphans.length) add({ check: 'orphan', severity: 'fix', spans: orphans, text: `${orphans.length} ${orphans.length === 1 ? 'span points' : 'spans point'} at a parent that is not in the trace, so ${orphans.length === 1 ? 'it is' : 'they are'} shown at the top.` })

  const llm = spans.filter((s) => s.kind === 'llm')
  const noUsage = llm.filter((s) => !s.tokens)
  if (noUsage.length) add({ check: 'no-usage', severity: 'note', spans: noUsage.map((s) => s.id), text: `${noUsage.length} of ${llm.length} model calls have no token counts, so cost cannot be worked out for them.` })
  if (options.expectThinking) {
    const bare = llm.filter((s) => !hasThinking(s))
    if (bare.length) add({ check: 'no-thinking', severity: 'note', spans: bare.map((s) => s.id), text: `${bare.length} of ${llm.length} model calls have no recorded reasoning, which is what explains why the agent chose a tool.` })
  }

  const generic = spans.filter((s) => !s.name.trim() || GENERIC.test(s.name.trim()))
  if (generic.length) add({ check: 'generic-name', severity: 'note', spans: generic.map((s) => s.id), text: `${generic.length} ${generic.length === 1 ? 'span has' : 'spans have'} a name that says nothing (${[...new Set(generic.map((s) => `"${s.name || '(empty)'}"`))].slice(0, 3).join(', ')}). Evaluations and dashboards find steps by name, so use stable ones.` })

  const noiseMs = options.noiseMs ?? 1
  const noiseCount = options.noiseCount ?? 20
  const tiny = new Map<string, string[]>()
  for (const s of spans) if (s.durationMs < noiseMs && s.kind !== 'llm' && s.kind !== 'tool') tiny.set(s.name, [...(tiny.get(s.name) ?? []), s.id])
  for (const [name, ids] of tiny) if (ids.length >= noiseCount) add({ check: 'noise', severity: 'note', spans: ids, text: `"${name}" appears ${ids.length} times and each lasts under ${noiseMs} ms. That is noise around the steps that matter.` })

  const silent = spans.filter((s) => s.status === 'error' && (s.output === undefined || s.output === null || s.output === ''))
  if (silent.length) add({ check: 'error-silent', severity: 'fix', spans: silent.map((s) => s.id), text: `${silent.length} failed ${silent.length === 1 ? 'span has' : 'spans have'} no output, so there is nothing to say why ${silent.length === 1 ? 'it' : 'they'} failed.` })

  const late = nodes.filter((n) => n.parent && n.span.startMs + n.span.durationMs > n.parent.span.startMs + n.parent.span.durationMs + 1).map((n) => n.span.id)
  if (late.length) add({ check: 'outlives-parent', severity: 'note', spans: late, text: `${late.length} ${late.length === 1 ? 'span ends' : 'spans end'} after ${late.length === 1 ? 'its' : 'their'} parent, which usually means a missing end time or work that was not awaited.` })

  const fix = findings.filter((f) => f.severity === 'fix').length
  const note = findings.length - fix
  const text = findings.length === 0 ? 'Nothing to fix. Each step is its own span, nested under the step that asked for it.' : `${fix} to fix, ${note} to note.`
  findings.sort((a, b) => Number(b.severity === 'fix') - Number(a.severity === 'fix'))
  return { findings, fix, note, text }
}
